const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const Redis = require('ioredis');

const app = express();
const redisClient = new Redis(process.env.REDIS_URL);
const store = new RedisStore({ client: redisClient, prefix: 'cart_sess:' });

app.use(session({
  store,
  secret: process.env.CART_SESSION_SECRET,
  resave: false,
  saveUninitialized: false
}));

app.post('/api/cart/sessions/:cartSessionId/release', (req, res) => {
  // Validate that the caller owns the cart session being released
  if (req.sessionID !== req.params.cartSessionId && req.session.role !== 'INVENTORY_ADMIN') {
    return res.status(403).json({ error: 'Unauthorized: cannot release another shopper\'s cart' });
  }

  store.destroy(req.params.cartSessionId, (err) => {
    if (err) {
      return res.status(500).json({ error: 'Failed to release reservation' });
    }
    res.json({ success: true, message: 'Cart reservation cleared' });
  });
});

app.listen(3300);
